import {h,render} from 'preact';
import {useState,useEffect,useRef} from 'preact/hooks';
import htm from 'htm';
import {animate,stagger,createScope} from './vendor/anime.esm.min.js';
const html=htm.bind(h);
const topics={generative:{label:'生成式检索',en:'GENERATIVE RETRIEVAL',line:'让模型记住文档的坐标。',desc:'从文档标识到神经索引，寻找检索的新路径。',tag:'索引 · 文档 ID'},cold:{label:'推荐冷启动',en:'COLD START',line:'第一步，也可以有方向。',desc:'当交互还很少，内容如何连接新的兴趣？',tag:'内容 · 推荐'},bias:{label:'曝光与评价',en:'EXPOSURE & EVALUATION',line:'看见指标之外的偏差。',desc:'理解曝光、缺失观测与离线评价的边界。',tag:'偏差 · 离线评价'}};
const grades={2:'明确匹配',1:'部分匹配',0:'主题不符'};
async function api(path,signal){const response=await fetch(path,{signal});if(!response.ok)throw Error(`请求失败（${response.status}）`);return response.json();}
function Icon({name,size=20}){
 const paths={search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',compass:'m15 9-2 4-4 2 2-4zM22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',arrow:'M5 12h14m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 6v15',activity:'M3 12h4l3-8 4 16 3-8h4',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',external:'M14 3h7v7M21 3 11 13M10 3H3v18h18v-7',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',back:'m11 5-7 7 7 7M4 12h17',check:'m5 12 4 4L19 6'};
 return html`<svg width=${size} height=${size} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d=${paths[name]||paths.spark}/></svg>`;
}
function TopicArt({topic}){
 return html`<svg class="topic-art" viewBox="0 0 280 114" fill="none" aria-hidden="true">
 ${topic==='generative'?html`<g stroke="currentColor" stroke-width="1.5"><path d="M35 83h62l36-50h55l41 50h22M97 83l36-50M133 33l36 50h60M169 83h-34"/><circle cx="35" cy="83" r="7"/><circle cx="97" cy="83" r="7"/><circle cx="133" cy="33" r="9"/><circle cx="188" cy="33" r="7"/><circle cx="229" cy="83" r="7"/></g><rect x="116" y="66" width="37" height="29" rx="6" fill="currentColor"/><path d="M127 75h15m-15 8h9" stroke="#eff4fc" stroke-width="2"/>`:topic==='cold'?html`<g stroke="currentColor"><ellipse cx="145" cy="60" rx="91" ry="32" transform="rotate(-18 145 60)"/><ellipse cx="145" cy="60" rx="65" ry="47" transform="rotate(23 145 60)"/><circle cx="145" cy="60" r="25" fill="currentColor" fill-opacity=".12"/><circle cx="145" cy="60" r="8" fill="currentColor"/><circle cx="61" cy="76" r="7" fill="#eaf0db"/><circle cx="204" cy="35" r="5" fill="currentColor"/></g>`:html`<g fill="currentColor">${Array.from({length:7},(_,x)=>Array.from({length:3},(_,y)=>html`<circle cx=${53+x*28} cy=${29+y*28} r=${x===3&&y===1?12:5} opacity=${x<3?'.3':'1'}/>`))}<path d="M134 13v90" stroke="currentColor" stroke-dasharray="3 4"/></g>`}</svg>`;
}
function HeroArt(){return html`<div class="hero-art" aria-label="论文轨道装饰图，非真实论文关系"><div class="art-caption"><span class="tiny-cross">+</span> IDEAS IN ORBIT <span>01—03</span></div>
 <svg class="orbit-scene" viewBox="0 0 420 302" fill="none" aria-hidden="true"><defs><linearGradient id="orb" x1="90" y1="25" x2="330" y2="280" gradientUnits="userSpaceOnUse"><stop stop-color="#b4d1ff"/><stop offset=".38" stop-color="#367aee"/><stop offset="1" stop-color="#12366b"/></linearGradient><linearGradient id="sheet" x1="135" y1="42" x2="285" y2="246" gradientUnits="userSpaceOnUse"><stop stop-color="#fff"/><stop offset="1" stop-color="#e1e8f0"/></linearGradient><linearGradient id="glass" x1="67" y1="100" x2="270" y2="236" gradientUnits="userSpaceOnUse"><stop stop-color="#c4d8ff" stop-opacity=".85"/><stop offset="1" stop-color="#4483e6" stop-opacity=".08"/></linearGradient><filter id="shadow" x="-60%" y="-50%" width="220%" height="240%"><feGaussianBlur stdDeviation="13"/></filter></defs>
 <circle cx="220" cy="149" r="112" fill="#e4eaf3"/><circle cx="220" cy="149" r="87" stroke="#cbd5e3" stroke-dasharray="2 6"/><ellipse cx="218" cy="153" rx="185" ry="63" transform="rotate(-24 218 153)" stroke="#b6c3d3"/>
 <ellipse cx="220" cy="252" rx="91" ry="13" fill="#4a6590" opacity=".16" filter="url(#shadow)"/>
 <g class="hero-pages"><path d="m126 86 119-32 77 46-15 113-125 43-67-52z" fill="url(#glass)" stroke="#a1b9d8"/><path d="m157 50 128 26 21 155-134-25z" fill="#c3cfde"/><path d="m155 43 128 26 21 155-134-25z" fill="url(#sheet)" stroke="#fff" stroke-width="1.5"/><path d="m170 66 59 12m-57 0 84 17m-80 10 85 18m-81-2 48 10m-45 7 78 16m-74-1 70 15m-65 4 35 7" stroke="#c6d1df" stroke-width="3"/><path d="m257 64 26 5 4 29-26-5z" fill="#d9e4f2"/>
 <path d="m117 136 92-28 75 51-7 80-92 32-74-53z" fill="url(#orb)" stroke="#8ab4fc"/><path d="m117 136 75 48 92-25M192 184l-7 87" stroke="#c3dbff" stroke-opacity=".55"/><path d="m150 163 43 27 48-16-3 26-47 17-42-28z" fill="#c9f477"/><path d="m168 183 24 15 27-9" stroke="#253b1f" stroke-width="2.5"/>
 </g><path d="M44 173c32 28 139 12 239-32 71-31 123-70 116-94" stroke="#a9bbd1"/><circle cx="58" cy="179" r="9" fill="#171f2a"/><circle cx="357" cy="96" r="10" fill="#c9f477" stroke="#b5d868"/><circle cx="327" cy="239" r="4" fill="#5488d9"/><path d="M85 77v13m-6-6h12m254 124v12m-6-6h12" stroke="#8998ad"/>
 <rect x="292" y="25" width="80" height="30" rx="15" fill="#fff" stroke="#d9e0e8"/><circle cx="307" cy="40" r="3" fill="#5389dd"/><text x="317" y="44" font-size="10" font-family="monospace" fill="#44546a">PAPER 01</text></svg><div class="art-foot"><span>检索 → 发现 → 阅读</span><small>图形示意</small></div></div>`;}
function describe(t){if(t.tool==='核心检索')return `${t.method.toUpperCase()} · ${t.eligible} 篇可检索，返回 ${t.returned} 篇`;if(t.tool==='候选内画像排序')return `${t.context==='same'?'同主题':'跨主题'}合成上下文，候选集合保持不变`;if(t.tool==='审查说明')return t.applies?'预设主题模型判断，未参与排序':'自定义查询，未套用预设等级';return `${t.doc_id} · 原始 v1 响应对应核验通过`;}
function Trace({result,status,error,paper,readState,readError,target}){return html`<div class="trace-content" aria-label="本次调用轨迹"><div class="panel-intro"><span class="eyebrow">EVERY STEP, IN THE OPEN</span><h3>沿着这次调用，回看依据。</h3><p>只展示实际返回的步骤，不模拟模型思考。</p></div>${status==='loading'?html`<div class="waiting" role="status"><i class="spinner"/>检索请求进行中，等待真实响应。</div>`:status==='error'?html`<div class="trace-failed" role="alert">检索请求失败 · ${error}</div>`:!result?html`<p class="muted">提交一次检索后，轨迹会出现在这里。</p>`:null}<ol class="trace-list">${(result?.trace||[]).map((t,i)=>html`<li key=${t.tool}><b class="step-dot">${String(i+1).padStart(2,'0')}</b><div><h4>${t.tool}<span>已返回</span></h4><p>${describe(t)}</p><details><summary>查看参数</summary><pre>${JSON.stringify(t,null,2)}</pre></details></div></li>`)}${readState==='loading'?html`<li class="pending"><b class="step-dot"><i class="spinner"/></b><div><h4>读取原摘要<span>进行中</span></h4><p>${target}</p></div></li>`:readState==='error'?html`<li class="failed"><b class="step-dot">!</b><div><h4>原摘要读取失败</h4><p>${readError}</p></div></li>`:(paper?.trace||[]).map(t=>html`<li key=${t.doc_id}><b class="step-dot">✓</b><div><h4>原摘要核验<span>已返回</span></h4><p>${describe(t)}</p><details><summary>查看参数</summary><pre>${JSON.stringify(t,null,2)}</pre></details></div></li>`)}</ol></div>`;}
function App(){
 const [meta,setMeta]=useState(null),[topic,setTopic]=useState('generative'),[q,setQ]=useState(''),[method,setMethod]=useState('bm25'),[context,setContext]=useState('none'),[view,setView]=useState('discover'),[tab,setTab]=useState('read'),[info,setInfo]=useState(false),[motion,setMotion]=useState(true);
 const [result,setResult]=useState(null),[paper,setPaper]=useState(null),[status,setStatus]=useState('idle'),[error,setError]=useState(''),[readState,setReadState]=useState('idle'),[readError,setReadError]=useState(''),[target,setTarget]=useState(null);
 const seq=useRef(0),readSeq=useRef(0),searchAbort=useRef(null),readAbort=useRef(null),root=useRef(null),infoButton=useRef(null),dialog=useRef(null);
 useEffect(()=>{const c=new AbortController();api('/api/meta',c.signal).then(m=>{setMeta(m);setQ(m.topics.generative.core);}).catch(e=>{if(e.name!=='AbortError')setError(e.message);});return()=>{c.abort();searchAbort.current?.abort();readAbort.current?.abort();};},[]);
 useEffect(()=>{if(!meta||!root.current)return;const scope=createScope({root:root.current,mediaQueries:{reduce:'(prefers-reduced-motion: reduce)'}}).add(self=>{if(!motion||self.matches.reduce)return;animate('[data-reveal]',{opacity:[0,1],y:[16,0],delay:stagger(65),duration:600,ease:'out(3)'});if(view==='discover')animate('.hero-pages',{y:[12,0],rotate:[-5,0],duration:1000,ease:'out(4)'});});return()=>scope.revert();},[meta,view,motion]);
 useEffect(()=>{window.scrollTo(0,0);},[view]);
 useEffect(()=>{if(info){dialog.current?.showModal();}else if(dialog.current?.open){dialog.current.close();infoButton.current?.focus();}},[info]);
 function clearReader(){readSeq.current++;readAbort.current?.abort();setPaper(null);setReadState('idle');setReadError('');setTarget(null);}
 function invalidate(){seq.current++;searchAbort.current?.abort();setStatus('idle');setResult(null);setError('');clearReader();}
 function choose(t,run=false){invalidate();setTopic(t);setQ(meta.topics[t].core);if(run)search(null,{topic:t,q:meta.topics[t].core});}
 function home(){invalidate();setView('discover');setTab('read');setQ(meta.topics[topic].core);}
 async function search(e,override={}){e?.preventDefault();const query=override.q??q;if(!query.trim())return;const n=++seq.current;searchAbort.current?.abort();const c=new AbortController();searchAbort.current=c;clearReader();setResult(null);setError('');setStatus('loading');setView('work');setTab('read');try{const value=await api('/api/search?'+new URLSearchParams({topic:override.topic??topic,q:query,method,context}),c.signal);if(n===seq.current){setResult(value);setStatus(value.papers.length?'returned':'empty');}}catch(e){if(n===seq.current&&e.name!=='AbortError'){setError(e.message);setStatus('error');}}}
 async function read(doc){const n=++readSeq.current;readAbort.current?.abort();const c=new AbortController();readAbort.current=c;setPaper(null);setTarget(doc);setReadState('loading');setReadError('');setTab('read');try{const value=await api('/api/paper/'+encodeURIComponent(doc),c.signal);if(n===readSeq.current){setPaper(value);setReadState('ready');}}catch(e){if(n===readSeq.current&&e.name!=='AbortError'){setReadError(e.message);setReadState('error');}}}
 if(!meta)return html`<div class="boot"><img src="/mark.svg" alt=""/><h1>Papertrail</h1><p role="status">${error||'正在打开你的研究空间…'}</p>${error&&html`<button onClick=${()=>location.reload()}>重新连接</button>`}</div>`;
 const busy=status==='loading',work=view==='work',count=(result?.trace.length||0)+(paper?.trace.length||0),selected=result?.papers.find(p=>p.doc_id===target);
 const buttonLabel=busy?'正在检索…':status==='error'?'重试检索':work?'重新检索':'开始检索';
 return html`<div ref=${root} class=${'studio '+(work?'is-work':'is-discover')+(motion?'':' motion-off')}><aside class="rail"><a href="/" class="brand"><img src="/mark.svg" alt=""/><span>Papertrail<i>RESEARCH STUDIO</i></span></a><button class="new-space" onClick=${home}><${Icon} name="plus" size=${17}/>新的探索<span>↗</span></button><p class="rail-label">WORKSPACE</p><nav aria-label="工作空间"><button class=${!work?'nav-item active':'nav-item'} aria-current=${!work?'page':undefined} onClick=${()=>setView('discover')}><${Icon} name="compass"/>发现<span>01</span></button><button class=${work?'nav-item active':'nav-item'} aria-current=${work?'page':undefined} onClick=${()=>setView('work')}><${Icon} name="grid"/>检索工作台<span>02</span></button></nav><div class="rail-divider"/><p class="rail-label">EXPLORE TOPICS</p><div class="rail-topics">${Object.entries(topics).map(([key,t],i)=>html`<button key=${key} class=${topic===key?'selected':''} aria-pressed=${topic===key} onClick=${()=>choose(key,true)}><span class=${'topic-dot dot-'+key}/>${t.label}<span class="topic-index">0${i+1}</span></button>`)}</div><div class="rail-bottom"><div class="rail-note"><div class="mini-orbits" aria-hidden="true">◎</div><strong>从一个问题出发</strong><p>每条线索，都能回到原文。</p></div><div class="connection"><span/> 本机已连接 <small>LOCAL</small></div><p class="rail-fine">42 篇开发目录 · 原始 v1</p></div></aside>
 <div class="canvas"><header class="topbar"><div class="breadcrumb">研究空间 <span>/</span><strong>${work?'检索工作台':'发现'}</strong></div><div class="top-actions"><button class="motion-toggle" aria-pressed=${!motion} onClick=${()=>setMotion(!motion)} aria-label=${motion?'关闭页面动效':'开启页面动效'}><${Icon} name="activity" size=${17}/><span>${motion?'动态开启':'动态关闭'}</span></button><button ref=${infoButton} class="info-toggle" onClick=${()=>setInfo(true)}><${Icon} name="info" size=${17}/>关于此空间</button><span class="avatar" aria-label="本地访客">P</span></div></header>
 <main class="main"><div class=${work?'work-heading':'hero'}>${work?html`<div><span class="eyebrow">FOLLOW THE EVIDENCE</span><h1>把线索，读成发现<span>。</span></h1><p>${topics[topic].label} <span class="separator">/</span> ${result?result.papers.length+' 篇候选':'准备检索'} <span class="separator">/</span> 原文可追溯</p></div><button class="back-home" onClick=${()=>setView('discover')}><${Icon} name="back" size=${16}/>返回发现</button>`:html`<div class="hero-copy" data-reveal><div class="edition"><span/> RESEARCH, WITH A TRAIL <b>VOL. 01</b></div><h1>沿着线索，<br/>发现<em>下一篇。</em></h1><p>从一个好问题，到一篇值得读的论文。<br/>让检索、兴趣与证据，在这里相遇。</p><div class="hero-proof"><span class="proof-mark"><${Icon} name="check" size=${13}/></span>真实目录 <i>·</i> 版本摘要 <i>·</i> 可追溯调用</div></div><div data-reveal><${HeroArt}/></div>`}</div>
 <form class="search-box" onSubmit=${search} data-reveal><div class="search-heading"><label for="query">${work?'继续探索你的问题':'你的下一次发现，从这里开始'}</label><span>${work?'SEARCH WORKSPACE':'ASK. EXPLORE. READ.'}</span></div><div class="query-row"><${Icon} name="search" size=${23}/><input id="query" value=${q} maxLength="1000" aria-label="你的论文需求" placeholder="输入英文核心术语，例如 generative retrieval" onInput=${e=>{setQ(e.target.value);invalidate();}}/><button class="search-submit" type="submit" disabled=${busy||!q.trim()} aria-busy=${busy}>${busy?html`<i class="spinner"/>`:null}${buttonLabel}<${Icon} name="arrow" size=${18}/></button></div><div class="search-options"><label>检索方法<select aria-label="检索方法" value=${method} onChange=${e=>{setMethod(e.target.value);invalidate();}}><option value="bm25">BM25</option><option value="tfidf">内容 TF-IDF</option></select></label><label>候选内排序<select aria-label="候选内排序" value=${context} onChange=${e=>{setContext(e.target.value);invalidate();}}><option value="none">保持检索顺序</option><option value="same">合成同主题上下文</option><option value="cross">合成跨主题上下文</option></select></label><button type="button" class="restore" onClick=${()=>{invalidate();setQ(meta.topics[topic].core);}}>恢复核心主题 ↗</button></div>${work?html`<p class=${'search-status '+status} role="status">${busy?'正在等待实际检索响应…':status==='returned'?'候选已返回。相关性需要结合原摘要判断。':status==='empty'?'没有词项匹配。修改术语后再试一次。':status==='error'?error:'输入英文核心术语，选择检索方式。'}</p>`:null}</form>
 ${!work?html`<section class="explore-section" aria-label="主题探索" data-reveal><div class="section-header"><div><span class="eyebrow">THREE WAYS TO GET CURIOUS</span><h2>换一个角度，打开思路。</h2></div><span class="section-meta">03 个探索方向</span></div><div class="topic-grid">${Object.entries(topics).map(([key,t],i)=>html`<button key=${key} class=${'explore-card explore-'+key} onClick=${()=>choose(key,true)}><div class="topic-top"><span>0${i+1}</span><span class="circle-arrow">↗</span></div><${TopicArt} topic=${key}/><span class="topic-en">${t.en}</span><h3>${t.label}</h3><p>${t.desc}</p><div class="topic-footer"><span>${t.tag}</span><span>探索主题 ↗</span></div></button>`)}</div></section><div class="bottom-note" data-reveal><span class="note-icon"><${Icon} name="book" size=${24}/></span><div><strong>发现之后，记得读原文。</strong><p>每篇候选都可以打开原始摘要，核对论文 ID、版本与来源。</p></div><span>KEEP YOUR CURIOSITY.<br/>KEEP THE EVIDENCE.</span></div>`:html`<div class="workbench" data-reveal><section class="result-panel" aria-label="检索结果" aria-busy=${busy}><div class="panel-heading"><h2>候选论文<span>${result?.papers.length??'—'}</span></h2><small>${method.toUpperCase()} <span>↘</span></small></div><div class="results-scroll">${busy?html`<div class="loading-results"><p>正在查询当前目录…</p>${[0,1,2].map(i=>html`<div class="skeleton" aria-hidden="true"><i/><i/><i/></div>`)}</div>`:!result?html`<div class="empty-state"><${Icon} name=${status==='error'?'info':'search'} size=${42}/><h3>${status==='error'?'这次检索未完成':'把你的问题写在上方'}</h3><p>${status==='error'?error:'提交后，在这里逐篇发现和阅读。'}</p></div>`:!result.papers.length?html`<div class="empty-state"><${Icon} name="search" size=${42}/><h3>还没有找到这条线索</h3><p>换一组核心术语，或恢复当前主题。</p></div>`:html`<p class="result-note">${result.review_applies?'等级为模型摘要判断，非独立真人评价。':'自定义需求 · 未套用预设主题等级。'}</p>${result.papers.map(p=>html`<article key=${p.doc_id} class=${'paper-card'+(target===p.doc_id?' selected':'')}><div class="paper-top"><span class="paper-number">${String(p.rank).padStart(2,'0')}</span><span class="paper-id">${p.doc_id} <i>·</i> v1</span><span class=${'grade grade-'+(p.review?.grade??'x')}>${p.review?grades[p.review.grade]:'未审查'}</span></div><h3><button class="paper-title" aria-pressed=${target===p.doc_id} onClick=${()=>read(p.doc_id)}>${p.title}</button></h3><p>${p.review?.reason||'阅读原摘要，判断它与你的问题是否有关。'}</p><div class="paper-bottom"><span>arXiv <i>↗</i></span><button class="read-action" onClick=${()=>read(p.doc_id)}>${target===p.doc_id&&readState==='loading'?'正在读取…':target===p.doc_id&&readState==='ready'?'正在阅读 ✓':'阅读原摘要'}<${Icon} name="arrow" size=${15}/></button></div></article>`)}`}</div></section>
 <section class="evidence-panel" aria-label="证据工作区"><div class="evidence-tabs" role="tablist" aria-label="证据与轨迹"><button role="tab" id="read-tab" aria-selected=${tab==='read'} aria-controls="read-panel" onClick=${()=>setTab('read')}><${Icon} name="book" size=${17}/>原摘要</button><button role="tab" id="trace-tab" aria-selected=${tab==='trace'} aria-controls="trace-panel" onClick=${()=>setTab('trace')}><${Icon} name="activity" size=${17}/>调用轨迹 <span>${count||'—'}</span></button><span class="evidence-dot"/></div>
 ${tab==='trace'?html`<div role="tabpanel" id="trace-panel" aria-labelledby="trace-tab" class="reader-scroll"><${Trace} result=${result} status=${status} error=${error} paper=${paper} readState=${readState} readError=${readError} target=${target}/>${result?.history.length>0&&html`<details class="history-panel"><summary>本次合成阅读上下文</summary><p>以下论文是预设合成历史，并非你的收藏。</p>${result.history.map(p=>html`<button onClick=${()=>read(p.doc_id)}>${p.title} ↗</button>`)}</details>`}</div>`:html`<div role="tabpanel" id="read-panel" aria-labelledby="read-tab" class="reader-scroll" aria-busy=${readState==='loading'}>${readState==='loading'?html`<div class="empty-state reader-loading" role="status"><i class="spinner"/><h3>正在核验原摘要</h3><p>${target} · 等待原始响应对应核验。</p></div>`:readState==='error'?html`<div class="empty-state reader-failed" role="alert"><${Icon} name="info" size=${40}/><h3>这次读取未完成</h3><p>${readError}</p><button class="retry" onClick=${()=>read(target)}>重试读取 ↗</button></div>`:paper?html`<div class="reader-body" key=${paper.paper.doc_id}><div class="verified"><${Icon} name="check" size=${13}/>原始 v1 缓存已核验<span>ORIGINAL ABSTRACT</span></div><h2>${paper.paper.title}</h2><div class="reader-meta"><span>arXiv</span><code>${paper.paper.version_key}</code></div><div class="abstract-heading"><span>摘要</span><span>ABSTRACT</span></div><p class="abstract" tabIndex="0" aria-label="完整原摘要">${paper.paper.abstract}</p>${selected?.review&&html`<details class="review-evidence"><summary>查看模型判断依据</summary><p>${selected.review.evidence}</p><small>非独立真人评价；摘要核验不代表验证论文结论。</small></details>`}<a class="source" href=${paper.paper.source_url} target="_blank" rel="noopener noreferrer">打开版本对应来源<${Icon} name="external" size=${16}/></a><p class="reader-disclaimer">摘要与原始响应对应，未核实全文实验结论。</p></div>`:html`<div class="empty-state reader-empty"><div class="empty-pages" aria-hidden="true"><span/><span/><span><${Icon} name="book" size=${34}/></span></div><span class="eyebrow">FOLLOW THE PAPER TRAIL</span><h3>好线索，值得读下去。</h3><p>选择左侧的一篇论文，<br/>在这里核对完整摘要与版本来源。</p></div>`}</div>`}</section></div>`}
 <footer><span>Papertrail <i>·</i> 让每次发现有迹可循</span><button onClick=${()=>setInfo(true)}>开发目录与评价边界 ↗</button></footer></main></div>
 <dialog ref=${dialog} class="about-dialog" onCancel=${()=>setInfo(false)} onClick=${e=>{if(e.target===dialog.current)setInfo(false);}} aria-labelledby="about-title"><div class="about-head"><span class="eyebrow">ABOUT THIS SPACE</span><button aria-label="关闭说明" onClick=${()=>setInfo(false)}><${Icon} name="close"/></button></div><h2 id="about-title">保持好奇，也保持边界。</h2><p>当前是本机研究演示，目录共${meta.catalog}篇，使用历史时点 ${meta.at.slice(0,10)} 的原始 v1 标题与摘要。搜索使用 BM25 或内容 TF-IDF。</p><p>同主题与跨主题上下文均为合成历史，仅调整核心候选内顺序，不代表访问者个人收藏。搜索请求没有调用 LLM。</p><p>预设主题等级是非独立模型摘要判断，不是真人相关性标注，不用于排名。自由查询没有对应标签。</p><details><summary>当前主题的审查判据</summary><p>${meta.rules[topic]}</p><p>42篇模型等级统计：明确${meta.summary[topic]['2']} / 部分${meta.summary[topic]['1']} / 不符${meta.summary[topic]['0']}。</p></details><p class="muted">轨道与节点是设计示意，不表示引用网络、相似度或检索关系。视觉参考与开源许可见本阶段说明。</p><button class="about-done" onClick=${()=>setInfo(false)}>知道了，继续探索<${Icon} name="arrow" size=${16}/></button></dialog></div>`;
}
document.getElementById('app').replaceChildren();render(html`<${App}/>`,document.getElementById('app'));
